model:
int: n = 30;
int: m = 40;

% Tile types
enum TILE_TYPE = SEA, CO, MO, FO, HI, GR, R, P, B, PR;

% Tile grid
array[1..n, 1..m] of var TILE_TYPE: grid;

% Constants
int: TOTAL_TILES = n * m;
int: SEA_TILES = round(0.15 * TOTAL_TILES);
int: LAND_TILES = TOTAL_TILES - SEA_TILES;
int: MO_TILES = round(0.10 * LAND_TILES);

% Count of each tile type
int: CO_TILES = LAND_TILES - MO_TILES;
int: FO_TILES = LAND_TILES / 5;
int: HI_TILES = LAND_TILES / 5;
int: GR_TILES = LAND_TILES / 5;

% Constraints for tile distribution
constraint sum(i in 1..n, j in 1..m)(if grid[i, j] == SEA then 1 else 0) == SEA_TILES;
constraint sum(i in 1..n, j in 1..m)(if grid[i, j] == MO then 1 else 0) == MO_TILES;
constraint sum(i in 1..n, j in 1..m)(if grid[i, j] == CO then 1 else 0) == CO_TILES;
constraint sum(i in 1..n, j in 1..m)(if grid[i, j] == FO then 1 else 0) == FO_TILES;
constraint sum(i in 1..n, j in 1..m)(if grid[i, j] == HI then 1 else 0) == HI_TILES;
constraint sum(i in 1..n, j in 1..m)(if grid[i, j] == GR then 1 else 0) == GR_TILES;

% Border constraints
constraint forall(i in 1..n)(grid[i, 1] == CO); % Left border
constraint forall(i in 1..n)(grid[i, m] == CO); % Right border
constraint forall(j in 1..m)(grid[1, j] == CO); % Top border
constraint forall(j in 1..m)(grid[n, j] == CO); % Bottom border

% River constraints
var int: river_start_x;
var int: river_start_y;
var int: river_end_x;
var int: river_end_y;

constraint grid[river_start_x, river_start_y] == MO;
constraint grid[river_end_x, river_end_y] == CO;

% Path constraints
var int: path_start_x;
var int: path_start_y;
var int: path_end_x;
var int: path_end_y;

% Ensure river and path can intersect or run parallel
constraint (river_start_x == path_start_x /
            river_start_y == path_start_y) -> (grid[river_start_x, river_start_y] == B);

% Output
output [
  show(grid)
];
